import shutil, openpyxl, re

shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

OUT_NAME = "OUT CAS"

def to_number(v):
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip().replace(',', '')
        if not s:
            return 0.0
        try:
            return float(s)
        except ValueError:
            return 0.0
    return 0.0

def item_key(ref):
    m = re.search(r'(\d+)$', ref)
    if m:
        return int(m.group(1))
    return 0

def bucket_for(ref):
    u = ref.upper()
    if u.startswith("PUR PURCHASE"):
        return "PUR"
    if u.startswith("PUR PAID"):
        return "PAID"
    if u.startswith("CASH SS"):
        return "CASH"
    if u.startswith("EXPRR"):
        return "EXPRR"
    return None

data = {k: {} for k in ("PUR","PAID","CASH","EXPRR")}

for name in wb.sheetnames:
    if name == OUT_NAME:
        break
    if name not in vals:
        continue
    vws = vals[name]
    for row in vws.iter_rows(min_row=2, values_only=True):
        if not row or len(row) < 2:
            continue
        ref = row[1]
        if ref is None:
            continue
        ref_s = str(ref).strip()
        if not ref_s:
            continue
        b = bucket_for(ref_s)
        if b is None:
            continue
        debit = to_number(row[2]) if len(row) > 2 else 0.0
        credit = to_number(row[3]) if len(row) > 3 else 0.0
        amt = debit + credit
        key = (item_key(ref_s), ref_s)
        data[b][key] = data[b].get(key, 0.0) + amt

if OUT_NAME not in wb.sheetnames:
    ws = wb.create_sheet(OUT_NAME)
else:
    ws = wb[OUT_NAME]

# clear existing data below header
max_clear_row = max(ws.max_row, 1529)
max_clear_col = max(ws.max_column, 15)
for r in range(2, max_clear_row + 1):
    for c in range(1, max_clear_col + 1):
        ws.cell(row=r, column=c).value = None

def clean_number(x):
    if isinstance(x, float) and x.is_integer():
        return int(x)
    return x

def write_table(item_col, ref_col, amt_col, bucket, region_rows):
    items = sorted(data[bucket].items(), key=lambda kv: (kv[0][0], kv[0][1]))
    total = sum(amt for _, amt in items)
    r = 2
    max_items = max(0, region_rows - 1)
    for idx, ((_, ref), amt) in enumerate(items, 1):
        if idx > max_items:
            break
        ws.cell(row=r, column=item_col, value=idx)
        ws.cell(row=r, column=ref_col, value=ref)
        ws.cell(row=r, column=amt_col, value=clean_number(amt))
        r += 1
    if region_rows > 0 and r <= 1 + region_rows:
        ws.cell(row=r, column=ref_col, value="TOTAL")
        ws.cell(row=r, column=amt_col, value=clean_number(total))
    return len(items), clean_number(total)

# answer region row counts
pur_count, pur_total = write_table(1, 2, 3, "PUR", 1528)
paid_count, paid_total = write_table(5, 6, 7, "PAID", 585)
cash_count, cash_total = write_table(9, 10, 11, "CASH", 12)
expr_count, expr_total = write_table(13, 14, 15, "EXPRR", 7)

print("PUR", pur_count, pur_total)
print("PAID", paid_count, paid_total)
print("CASH", cash_count, cash_total)
print("EXPRR", expr_count, expr_total)

wb.save(OUT)
